from attr import attrs, attrib
from attr.validators import disabled
from attr.exceptions import ValidationError

@attrs
class C:
    x = attrib(validator=lambda inst, name, value: (
        None if isinstance(value, int) else exec('raise TypeError("not an int")')
    ))

# This is a bit tricky because TypeError might be raised by the validator
# but attrs usually wraps validator exceptions or just lets them propagate.
# Let's use a simpler validator.

@attrs
class C2:
    x = attrib(validator=lambda inst, name, value: (
        None if isinstance(value, int) else (_ for _ in ()).throw(TypeError("not an int"))
    ))
# Actually, just raise it normally.

@attrs
class C3:
    x = attrib(validator=lambda inst, name, value: (
        None if isinstance(value, int) else exec('raise TypeError("not an int")')
    ))
# Wait, exec() doesn't work like that in a lambda.

def my_validator(instance, attribute, value):
    if not isinstance(value, int):
        raise TypeError("not an int")

@attrs
class C4:
    x = attrib(validator=my_validator)

try:
    with disabled():
        with disabled():
            pass
        # Now we are back in the first disabled() block.
        # Validators should still be disabled.
        C4(x="not_int")
        print("Success: validators still disabled")
except TypeError:
    print("Failure: validators were re-enabled")
except Exception as e:
    print(f"Unexpected exception: {e}")

